import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.BrO6lPIi.js";const p=JSON.parse('{"title":"MCP 客户端实现","description":"本文面向 MCP（Model Context Protocol）客户端实现，聚焦 Agent 端如何作为 MCP 客户端接入外部工具服务器。","frontmatter":{"title":"MCP 客户端实现","description":"本文面向 MCP（Model Context Protocol）客户端实现，聚焦 Agent 端如何作为 MCP 客户端接入外部工具服务器。"},"headers":[],"relativePath":"工具生态系统/MCP-协议扩展/MCP-客户端实现/index.md","filePath":"工具生态系统/MCP-协议扩展/MCP-客户端实现/index.md","lastUpdated":null}'),i={name:"工具生态系统/MCP-协议扩展/MCP-客户端实现/index.md"};function c(l,e,n,d,s,g){return r(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="mcp-客户端实现" tabindex="-1">MCP 客户端实现 <a class="header-anchor" href="#mcp-客户端实现" aria-label="Permalink to &quot;MCP 客户端实现&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js" target="_blank" rel="noreferrer">agent/src/mcp/client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js" target="_blank" rel="noreferrer">agent/src/mcp/registry.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-client-test.js" target="_blank" rel="noreferrer">agent/test/mcp-client-test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-test-server.cjs" target="_blank" rel="noreferrer">agent/test/mcp-test-server.cjs</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/locales/en.json" target="_blank" rel="noreferrer">agent/src/locales/en.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/locales/zh.json" target="_blank" rel="noreferrer">agent/src/locales/zh.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源管理">性能与资源管理</a></li><li><a href="#配置选项与连接参数调优">配置选项与连接参数调优</a></li><li><a href="#故障排查与调试指南">故障排查与调试指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文面向 MCP（Model Context Protocol）客户端实现，聚焦 Agent 端如何作为 MCP 客户端接入外部工具服务器。文档覆盖以下目标：</p><ul><li>连接建立过程与四种传输协议差异：stdio、SSE、Streamable HTTP、WebSocket。</li><li>消息序列化与反序列化机制，以及工具自动发现流程。</li><li>远程工具调用完整链路：参数校验、请求构建、响应处理、错误处理与重试策略。</li><li>连接池管理、超时控制、资源清理策略。</li><li>客户端配置项、连接参数调优与故障恢复方案。</li><li>实际连接示例与调试技巧。</li></ul><p>本项目采用双进程架构：Chrome 扩展端通过本地 HTTP/WebSocket 调用 Agent；Agent 再作为 MCP 客户端连接第三方 MCP Server。MCP 客户端相关逻辑集中在 <code>agent/src/mcp</code> 目录下，由 <code>server.js</code> 暴露 REST API 供扩展端调用。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>MCP 客户端实现主要位于 Agent 端的 <code>agent/src/mcp</code> 目录，包含三个核心文件：</p><ul><li><code>client.js</code>：封装单个 MCP 客户端实例，负责传输层选择、连接、工具列表获取和工具调用。</li><li><code>registry.js</code>：维护已连接的 MCP 客户端映射表，提供批量初始化、状态查询、工具扁平化、单服务连接/断开、全局关闭等能力。</li><li><code>mcp-config.js</code>：持久化 MCP Server 配置，提供带缓存的加载、写入锁、增删改查接口。</li></ul><p>Agent 主服务 <code>server.js</code> 将 MCP 管理能力暴露为 REST API，例如添加/删除/启用/禁用 MCP Server、连接/断开、查询工具列表、调用工具等。</p><pre class="mermaid">graph TB
subgraph &quot;扩展端&quot;
BG[&quot;Background 脚本&lt;br/&gt;工具注册与调用&quot;]
end
subgraph &quot;Agent 端&quot;
SRV[&quot;HTTP 服务&lt;br/&gt;/api/mcp/* 路由&quot;]
REG[&quot;MCP 注册表&lt;br/&gt;registry.js&quot;]
CFG[&quot;MCP 配置管理&lt;br/&gt;mcp-config.js&quot;]
CLI[&quot;MCP 客户端&lt;br/&gt;client.js&quot;]
end
subgraph &quot;外部 MCP 服务器&quot;
STDIO[&quot;本地子进程&lt;br/&gt;stdio 传输&quot;]
SSE_SVR[&quot;SSE 服务端&quot;]
HTTP_SVR[&quot;Streamable HTTP 服务端&quot;]
WS_SVR[&quot;WebSocket 服务端&quot;]
end
BG --&gt; SRV
SRV --&gt; REG
REG --&gt; CLI
REG --&gt; CFG
CLI --&gt; STDIO
CLI --&gt; SSE_SVR
CLI --&gt; HTTP_SVR
CLI --&gt; WS_SVR
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L127</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>本节从职责边界角度梳理 MCP 客户端相关组件。</p><table tabindex="0"><thead><tr><th>组件</th><th>主要职责</th><th>关键方法/属性</th><th>对外暴露点</th></tr></thead><tbody><tr><td><code>McpClient</code></td><td>单个 MCP 客户端生命周期管理</td><td><code>_createTransport()</code>、<code>connect()</code>、<code>callTool()</code>、<code>disconnect()</code>、<code>getStatus()</code></td><td>被 <code>registry.js</code> 使用</td></tr><tr><td><code>registry.js</code></td><td>多 MCP 客户端注册表、工具聚合、连接管理</td><td><code>initializeMcpRegistry()</code>、<code>getMcpServersStatus()</code>、<code>getMcpTools()</code>、<code>callMcpTool()</code>、<code>connectMcpServer()</code>、<code>disconnectMcpServer()</code>、<code>shutdownMcpRegistry()</code></td><td>被 <code>server.js</code> 使用</td></tr><tr><td><code>mcp-config.js</code></td><td>MCP Server 配置文件读写、内存缓存、写入互斥锁</td><td><code>loadMcpConfig()</code>、<code>saveMcpConfig()</code>、<code>addMcpServer()</code>、<code>removeMcpServer()</code>、<code>toggleMcpServer()</code></td><td>被 <code>registry.js</code> 使用</td></tr><tr><td><code>server.js</code> MCP 路由</td><td>将 MCP 操作暴露为 HTTP API</td><td><code>/api/mcp/servers</code>、<code>/api/mcp/servers/connect</code>、<code>/api/mcp/servers/disconnect</code>、<code>/api/mcp/tools</code>、<code>/api/mcp/call</code></td><td>被扩展端 Background 调用</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L19-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L19-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L14-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L14-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>MCP 客户端在 Agent 中处于“扩展端 → Agent → 外部 MCP Server”链路的中间层。整体数据流如下：</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端 Background&quot;
participant Api as &quot;Agent HTTP API&quot;
participant Reg as &quot;MCP 注册表&quot;
participant Cli as &quot;MCP 客户端&quot;
participant Tr as &quot;传输层&quot;
participant Srv as &quot;外部 MCP 服务器&quot;
Ext-&gt;&gt;Api : &quot;POST /api/mcp/servers/connect&quot;
Api-&gt;&gt;Reg : &quot;connectMcpServer(serverId)&quot;
Reg-&gt;&gt;Cli : &quot;new McpClient(config)&quot;
Cli-&gt;&gt;Tr : &quot;_createTransport()&quot;
Tr--&gt;&gt;Cli : &quot;Stdio/SSE/StreamableHTTP/WebSocket&quot;
Cli-&gt;&gt;Srv : &quot;connect + initialize&quot;
Srv--&gt;&gt;Cli : &quot;serverInfo + capabilities&quot;
Cli-&gt;&gt;Srv : &quot;listTools&quot;
Srv--&gt;&gt;Cli : &quot;tools[]&quot;
Cli--&gt;&gt;Reg : &quot;connected = true, tools&quot;
Reg--&gt;&gt;Api : &quot;{ success, toolCount }&quot;
Api--&gt;&gt;Ext : &quot;连接结果&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1885-L1891" target="_blank" rel="noreferrer">agent/src/server.js#L1885-L1891</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L133-L154" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L133-L154</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L127</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="mcpclient-单个-mcp-客户端实现" tabindex="-1"><code>McpClient</code>：单个 MCP 客户端实现 <a class="header-anchor" href="#mcpclient-单个-mcp-客户端实现" aria-label="Permalink to &quot;\`McpClient\`：单个 MCP 客户端实现&quot;">​</a></h3><p><code>McpClient</code> 是 MCP 客户端的核心类，封装了传输层选择、连接、工具发现、工具调用和资源释放。</p><h4 id="传输层选择" tabindex="-1">传输层选择 <a class="header-anchor" href="#传输层选择" aria-label="Permalink to &quot;传输层选择&quot;">​</a></h4><p><code>_createTransport()</code> 根据 <code>serverConfig.transport</code> 创建对应传输实例：</p><ul><li><code>stdio</code>：默认值，需要 <code>command</code>、可选 <code>args</code>、<code>env</code>、<code>cwd</code>。</li><li><code>sse</code>：需要 <code>url</code>，支持通过 <code>headers</code> 注入请求头。</li><li><code>streamableHttp</code>：需要 <code>url</code>，支持通过 <code>headers</code> 注入请求头。</li><li><code>websocket</code>：需要 <code>url</code>。</li></ul><p>如果缺少必要字段，会抛出国际化错误信息，例如“SSE 传输需要提供 url”“stdio 传输需要提供 command”。</p><pre class="mermaid">flowchart TD
Start([&quot;创建传输层&quot;]) --&gt; CheckType[&quot;读取 transport 类型&quot;]
CheckType --&gt; |sse| CheckSseUrl[&quot;检查 url 是否存在&quot;]
CheckType --&gt; |streamableHttp| CheckHttpUrl[&quot;检查 url 是否存在&quot;]
CheckType --&gt; |websocket| CheckWsUrl[&quot;检查 url 是否存在&quot;]
CheckType --&gt; |stdio| CheckCmd[&quot;检查 command 是否存在&quot;]
CheckSseUrl --&gt; |存在| CreateSse[&quot;创建 SSEClientTransport&quot;]
CheckSseUrl --&gt; |不存在| ThrowSse[&quot;抛出 SSE 缺少 url 错误&quot;]
CheckHttpUrl --&gt; |存在| CreateHttp[&quot;创建 StreamableHTTPClientTransport&quot;]
CheckHttpUrl --&gt; |不存在| ThrowHttp[&quot;抛出 StreamableHTTP 缺少 url 错误&quot;]
CheckWsUrl --&gt; |存在| CreateWs[&quot;创建 WebSocketClientTransport&quot;]
CheckWsUrl --&gt; |不存在| ThrowWs[&quot;抛出 WebSocket 缺少 url 错误&quot;]
CheckCmd --&gt; |存在| CreateStdio[&quot;创建 StdioClientTransport&quot;]
CheckCmd --&gt; |不存在| ThrowStdio[&quot;抛出 stdio 缺少 command 错误&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L50-L94" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L50-L94</a></li></ul><h4 id="连接与工具发现" tabindex="-1">连接与工具发现 <a class="header-anchor" href="#连接与工具发现" aria-label="Permalink to &quot;连接与工具发现&quot;">​</a></h4><p><code>connect()</code> 执行以下步骤：</p><ol><li>若已连接则直接返回成功。</li><li>创建传输层实例。</li><li>创建 SDK 客户端实例，名称固定为 <code>ai-helper-agent</code>，版本固定为 <code>1.3.4</code>。</li><li>调用 SDK 的 <code>connect</code> 完成握手。</li><li>读取服务器版本和能力。</li><li>调用 <code>listTools</code> 获取工具列表并缓存到 <code>this.tools</code>。</li><li>设置 <code>connected = true</code>，返回连接结果。</li></ol><p>连接失败时会调用 <code>disconnect()</code> 清理资源，并返回包含错误信息的对象。</p><pre class="mermaid">sequenceDiagram
participant C as &quot;McpClient&quot;
participant T as &quot;传输层&quot;
participant SDK as &quot;SDK Client&quot;
participant S as &quot;MCP 服务器&quot;
C-&gt;&gt;C : &quot;connect()&quot;
alt 已连接
C--&gt;&gt;C : &quot;直接返回成功&quot;
else 未连接
C-&gt;&gt;T : &quot;_createTransport()&quot;
T--&gt;&gt;C : &quot;transport 实例&quot;
C-&gt;&gt;SDK : &quot;new Client({ name, version })&quot;
C-&gt;&gt;SDK : &quot;connect(transport)&quot;
SDK-&gt;&gt;S : &quot;initialize&quot;
S--&gt;&gt;SDK : &quot;serverInfo, capabilities&quot;
C-&gt;&gt;SDK : &quot;listTools&quot;
SDK-&gt;&gt;S : &quot;tools/list&quot;
S--&gt;&gt;SDK : &quot;tools[]&quot;
SDK--&gt;&gt;C : &quot;tools&quot;
C-&gt;&gt;C : &quot;connected = true&quot;
C--&gt;&gt;C : &quot;返回 { success, toolCount }&quot;
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L127</a></li></ul><h4 id="工具调用" tabindex="-1">工具调用 <a class="header-anchor" href="#工具调用" aria-label="Permalink to &quot;工具调用&quot;">​</a></h4><p><code>callTool()</code> 的流程：</p><ol><li>检查是否已连接，未连接则返回“MCP Server 未连接”错误。</li><li>调用 SDK 的 <code>callTool</code>，传入工具名和参数。</li><li>如果返回结果中包含 <code>error</code>，转换为失败响应。</li><li>否则从 <code>result.content</code> 中提取 <code>type === &#39;text&#39;</code> 的内容，拼接为文本。</li><li>返回 <code>{ success, content, raw }</code>。</li><li>捕获异常后返回国际化错误信息。</li></ol><p>当前实现没有显式重试逻辑，但上层 Background 侧对工具调用结果有重试机制。</p><pre class="mermaid">flowchart TD
Start([&quot;调用工具&quot;]) --&gt; Connected{&quot;是否已连接&quot;}
Connected --&gt; |否| ReturnNotConnected[&quot;返回未连接错误&quot;]
Connected --&gt; |是| CallSdk[&quot;调用 SDK callTool&quot;]
CallSdk --&gt; HasError{&quot;返回结果是否包含 error&quot;}
HasError --&gt; |是| ReturnError[&quot;返回失败错误&quot;]
HasError --&gt; |否| ExtractText[&quot;提取 text 类型内容&quot;]
ExtractText --&gt; JoinText[&quot;拼接为字符串&quot;]
JoinText --&gt; ReturnSuccess[&quot;返回成功结果&quot;]
CallSdk --&gt; CatchErr[&quot;捕获异常&quot;]
CatchErr --&gt; ReturnCallError[&quot;返回调用异常错误&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L158" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L158</a></li></ul><h4 id="连接状态与资源清理" tabindex="-1">连接状态与资源清理 <a class="header-anchor" href="#连接状态与资源清理" aria-label="Permalink to &quot;连接状态与资源清理&quot;">​</a></h4><p><code>disconnect()</code> 会：</p><ul><li>设置 <code>connected = false</code>。</li><li>清空 <code>tools</code>。</li><li>尝试关闭 SDK 客户端。</li><li>尝试关闭传输层。</li><li>将引用置空。</li></ul><p><code>getStatus()</code> 返回当前服务的 ID、名称、连接状态、工具数量和服务器信息。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li></ul><h3 id="registry-js-mcp-工具注册表" tabindex="-1"><code>registry.js</code>：MCP 工具注册表 <a class="header-anchor" href="#registry-js-mcp-工具注册表" aria-label="Permalink to &quot;\`registry.js\`：MCP 工具注册表&quot;">​</a></h3><p><code>registry.js</code> 维护一个 <code>Map&lt;serverId, McpClient&gt;</code>，提供多服务管理、工具扁平化和统一调用入口。</p><h4 id="启动时初始化" tabindex="-1">启动时初始化 <a class="header-anchor" href="#启动时初始化" aria-label="Permalink to &quot;启动时初始化&quot;">​</a></h4><p><code>initializeMcpRegistry()</code> 会：</p><ol><li>加载 MCP 配置。</li><li>遍历所有启用的 server。</li><li>为每个 server 创建 <code>McpClient</code> 并连接。</li><li>记录成功连接数和失败列表。</li><li>输出日志提示连接情况。</li></ol><h4 id="工具列表获取" tabindex="-1">工具列表获取 <a class="header-anchor" href="#工具列表获取" aria-label="Permalink to &quot;工具列表获取&quot;">​</a></h4><p><code>getMcpTools()</code> 会：</p><ol><li>遍历所有已连接 client。</li><li>过滤掉未连接或指定 serverId 不匹配的服务。</li><li>将每个工具的 <code>name</code>、<code>description</code>、<code>inputSchema</code> 扁平化为统一结构。</li><li>返回 <code>{ success, tools }</code>。</li></ol><h4 id="工具调用-1" tabindex="-1">工具调用 <a class="header-anchor" href="#工具调用-1" aria-label="Permalink to &quot;工具调用&quot;">​</a></h4><p><code>callMcpTool()</code> 会：</p><ol><li>查找 serverId 对应的 client。</li><li>检查 client 是否存在且已连接。</li><li>调用底层 <code>client.callTool()</code>。</li><li>返回调用结果。</li></ol><h4 id="连接管理" tabindex="-1">连接管理 <a class="header-anchor" href="#连接管理" aria-label="Permalink to &quot;连接管理&quot;">​</a></h4><ul><li><code>connectMcpServer()</code>：先断开已有连接，再新建 client 并连接。</li><li><code>disconnectMcpServer()</code>：断开指定服务并从 Map 移除。</li><li><code>shutdownMcpRegistry()</code>：Agent 关闭时统一断开所有连接并清空 Map。</li></ul><pre class="mermaid">classDiagram
class Registry {
-clients : Map
+initializeMcpRegistry() Promise
+getMcpServersStatus() Object
+getMcpTools(serverId?) Object
+callMcpTool(serverId, toolName, args) Promise
+connectMcpServer(serverId) Promise
+disconnectMcpServer(serverId) Promise
+shutdownMcpRegistry() Promise
}
class McpClient {
+serverId
+serverName
+connected
+tools
+connect() Promise
+callTool(toolName, args) Promise
+disconnect() Promise
+getStatus() Object
}
Registry --&gt; McpClient : &quot;管理多个实例&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L19-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L19-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li></ul><h3 id="mcp-config-js-mcp-配置管理" tabindex="-1"><code>mcp-config.js</code>：MCP 配置管理 <a class="header-anchor" href="#mcp-config-js-mcp-配置管理" aria-label="Permalink to &quot;\`mcp-config.js\`：MCP 配置管理&quot;">​</a></h3><p>该模块负责 MCP Server 配置的持久化与内存缓存。</p><h4 id="配置路径与缓存" tabindex="-1">配置路径与缓存 <a class="header-anchor" href="#配置路径与缓存" aria-label="Permalink to &quot;配置路径与缓存&quot;">​</a></h4><ul><li>配置文件路径：用户目录下的 <code>.ai-helper-agent/mcp_servers.json</code>。</li><li>内存缓存：<code>configCache</code> 和 <code>configCacheMtime</code>，避免重复解析。</li><li>写入互斥锁：<code>writeLock</code> 保证并发写安全。</li></ul><h4 id="主要接口" tabindex="-1">主要接口 <a class="header-anchor" href="#主要接口" aria-label="Permalink to &quot;主要接口&quot;">​</a></h4><ul><li><code>loadMcpConfig()</code>：带 mtime 检测的加载函数，首次不存在时创建默认空配置。</li><li><code>saveMcpConfig()</code>：加锁写入并更新缓存。</li><li><code>addMcpServer()</code>：新增或更新 server。</li><li><code>removeMcpServer()</code>：按 id 删除。</li><li><code>toggleMcpServer()</code>：切换 enabled 状态。</li></ul><pre class="mermaid">flowchart TD
Load[&quot;loadMcpConfig()&quot;] --&gt; CheckMtime[&quot;检查文件 mtime&quot;]
CheckMtime --&gt; |命中缓存| ReturnCache[&quot;返回缓存&quot;]
CheckMtime --&gt; |未命中| CheckFile{&quot;文件是否存在&quot;}
CheckFile --&gt; |不存在| CreateDefault[&quot;创建默认空配置&quot;]
CheckFile --&gt; |存在| ReadFile[&quot;读取并解析 JSON&quot;]
CreateDefault --&gt; SaveCache[&quot;保存缓存&quot;]
ReadFile --&gt; ValidateServers[&quot;确保 servers 字段存在&quot;]
ValidateServers --&gt; SaveCache
SaveCache --&gt; ReturnResult[&quot;返回配置&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L28-L64" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L28-L64</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li></ul><h3 id="server-js-mcp-rest-api-路由" tabindex="-1"><code>server.js</code>：MCP REST API 路由 <a class="header-anchor" href="#server-js-mcp-rest-api-路由" aria-label="Permalink to &quot;\`server.js\`：MCP REST API 路由&quot;">​</a></h3><p><code>server.js</code> 将 MCP 管理能力暴露为 HTTP API，关键路由如下：</p><table tabindex="0"><thead><tr><th>路由</th><th>方法</th><th>功能</th><th>参数校验</th></tr></thead><tbody><tr><td><code>/api/mcp/servers</code></td><td>POST</td><td>添加 MCP Server</td><td>校验 id、http 需要 url、stdio 需要 command、stdio 命令安全检查</td></tr><tr><td><code>/api/mcp/servers</code></td><td>DELETE</td><td>删除 MCP Server</td><td>校验 id</td></tr><tr><td><code>/api/mcp/servers/connect</code></td><td>POST</td><td>连接指定 MCP Server</td><td>校验 id</td></tr><tr><td><code>/api/mcp/servers/disconnect</code></td><td>POST</td><td>断开指定 MCP Server</td><td>校验 id</td></tr><tr><td><code>/api/mcp/servers/toggle</code></td><td>POST</td><td>启用/禁用 MCP Server</td><td>校验 id 和 enabled；禁用时先断开连接</td></tr><tr><td><code>/api/mcp/call</code></td><td>POST</td><td>调用 MCP 工具</td><td>校验 serverId 和 toolName</td></tr><tr><td><code>/api/mcp/servers</code></td><td>GET</td><td>获取所有 MCP Server 状态</td><td>无参数</td></tr><tr><td><code>/api/mcp/tools</code></td><td>GET</td><td>获取所有 MCP 工具</td><td>可选 serverId</td></tr></tbody></table><p>其中，stdio 传输会对 <code>command + args</code> 进行安全校验，防止 MCP 成为命令管控后门。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端&quot;
participant Api as &quot;Agent API&quot;
participant Reg as &quot;MCP 注册表&quot;
Ext-&gt;&gt;Api : &quot;POST /api/mcp/call&quot;
Api-&gt;&gt;Api : &quot;校验 serverId、toolName&quot;
Api-&gt;&gt;Reg : &quot;callMcpTool(serverId, toolName, args)&quot;
Reg-&gt;&gt;Reg : &quot;查找 client&quot;
Reg-&gt;&gt;Reg : &quot;检查 connected&quot;
Reg-&gt;&gt;Reg : &quot;调用底层 client.callTool&quot;
Reg--&gt;&gt;Api : &quot;返回结果&quot;
Api--&gt;&gt;Ext : &quot;JSON 响应&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1915-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1915-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>MCP 客户端实现的依赖关系如下：</p><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Registry[&quot;registry.js&quot;]
Registry --&gt; Config[&quot;mcp-config.js&quot;]
Registry --&gt; Client[&quot;client.js&quot;]
Client --&gt; SDK[&quot;@modelcontextprotocol/sdk&quot;]
Client --&gt; TransportStdio[&quot;StdioClientTransport&quot;]
Client --&gt; TransportSse[&quot;SSEClientTransport&quot;]
Client --&gt; TransportHttp[&quot;StreamableHTTPClientTransport&quot;]
Client --&gt; TransportWs[&quot;WebSocketClientTransport&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L5" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L6" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L6</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L6" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L5" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li></ul><h2 id="性能与资源管理" tabindex="-1">性能与资源管理 <a class="header-anchor" href="#性能与资源管理" aria-label="Permalink to &quot;性能与资源管理&quot;">​</a></h2><h3 id="连接池管理" tabindex="-1">连接池管理 <a class="header-anchor" href="#连接池管理" aria-label="Permalink to &quot;连接池管理&quot;">​</a></h3><p>当前实现不是传统意义上的连接池，而是“注册表 + 单例 per server”模式：</p><ul><li>每个启用的 MCP Server 对应一个 <code>McpClient</code> 实例。</li><li><code>registry.js</code> 中的 <code>clients</code> Map 充当轻量级连接池。</li><li>重启或手动重连时，会先断开旧连接再创建新实例。</li></ul><p>这种设计适合 MCP Server 数量较少、连接数可控的场景。</p><h3 id="超时控制" tabindex="-1">超时控制 <a class="header-anchor" href="#超时控制" aria-label="Permalink to &quot;超时控制&quot;">​</a></h3><ul><li><code>McpClient</code> 本身没有显式超时配置。</li><li>超时控制主要由 SDK 和传输层实现决定。</li><li>Agent 层的通用请求超时逻辑不在 MCP 客户端内部体现。</li></ul><h3 id="资源清理策略" tabindex="-1">资源清理策略 <a class="header-anchor" href="#资源清理策略" aria-label="Permalink to &quot;资源清理策略&quot;">​</a></h3><ul><li><code>disconnect()</code> 会关闭 SDK 客户端和传输层。</li><li><code>shutdownMcpRegistry()</code> 会在 Agent 关闭时统一清理所有连接。</li><li>配置写入使用互斥锁，避免并发写导致文件损坏。</li></ul><h3 id="工具发现与缓存" tabindex="-1">工具发现与缓存 <a class="header-anchor" href="#工具发现与缓存" aria-label="Permalink to &quot;工具发现与缓存&quot;">​</a></h3><ul><li>工具列表在连接成功后立即拉取并缓存到 <code>client.tools</code>。</li><li>Background 侧对 MCP 工具列表有 30 秒缓存，减少频繁网络请求。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L19-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L19-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1196-L1231" target="_blank" rel="noreferrer">src/background/index.js#L1196-L1231</a></li></ul><h2 id="配置选项与连接参数调优" tabindex="-1">配置选项与连接参数调优 <a class="header-anchor" href="#配置选项与连接参数调优" aria-label="Permalink to &quot;配置选项与连接参数调优&quot;">​</a></h2><h3 id="mcp-server-配置字段" tabindex="-1">MCP Server 配置字段 <a class="header-anchor" href="#mcp-server-配置字段" aria-label="Permalink to &quot;MCP Server 配置字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填条件</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>所有传输</td><td>服务唯一标识</td></tr><tr><td><code>name</code></td><td>string</td><td>可选</td><td>显示名称，默认为 id</td></tr><tr><td><code>transport</code></td><td>string</td><td>可选</td><td>传输类型：<code>stdio</code>、<code>sse</code>、<code>streamableHttp</code>、<code>websocket</code></td></tr><tr><td><code>url</code></td><td>string</td><td>http 类传输必填</td><td>SSE、Streamable HTTP、WebSocket 需要 URL</td></tr><tr><td><code>command</code></td><td>string</td><td>stdio 传输必填</td><td>本地子进程命令</td></tr><tr><td><code>args</code></td><td>array</td><td>stdio 传输可选</td><td>子进程参数数组</td></tr><tr><td><code>env</code></td><td>object</td><td>stdio 传输可选</td><td>子进程环境变量</td></tr><tr><td><code>cwd</code></td><td>string</td><td>stdio 传输可选</td><td>子进程工作目录</td></tr><tr><td><code>headers</code></td><td>object</td><td>http 类传输可选</td><td>自定义请求头</td></tr><tr><td><code>enabled</code></td><td>boolean</td><td>可选</td><td>是否启用，影响启动时自动连接</td></tr></tbody></table><h3 id="传输协议适用场景" tabindex="-1">传输协议适用场景 <a class="header-anchor" href="#传输协议适用场景" aria-label="Permalink to &quot;传输协议适用场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>传输协议</th><th>适用场景</th><th>优点</th><th>注意事项</th></tr></thead><tbody><tr><td>stdio</td><td>本地 MCP Server 子进程</td><td>简单、低延迟、适合本地工具</td><td>需命令安全检查，敏感命令可能被拦截</td></tr><tr><td>SSE</td><td>单向流式 HTTP 服务</td><td>兼容现有 HTTP 基础设施</td><td>SDK 升级计划中标记为 deprecated</td></tr><tr><td>streamableHttp</td><td>现代 MCP Server</td><td>官方推荐、支持更多特性</td><td>需要服务端支持 Streamable HTTP</td></tr><tr><td>websocket</td><td>双向实时通信</td><td>低延迟、适合长连接</td><td>非官方标准，兼容性需谨慎评估</td></tr></tbody></table><h3 id="连接参数调优建议" tabindex="-1">连接参数调优建议 <a class="header-anchor" href="#连接参数调优建议" aria-label="Permalink to &quot;连接参数调优建议&quot;">​</a></h3><ul><li><strong>stdio</strong>：优先使用白名单命令，避免高危命令；合理设置 <code>env</code> 传递敏感配置。</li><li><strong>SSE/Streamable HTTP</strong>：通过 <code>headers</code> 注入认证头；注意 URL 必须有效。</li><li><strong>WebSocket</strong>：仅在与服务端明确兼容时使用。</li><li><strong>连接重试</strong>：当前 MCP 客户端无内置重试，可在上层实现指数退避重试。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L50-L94" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L50-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1875" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1875</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/docs/MCP-UPGRADE-ANALYSIS.md#L148-L189" target="_blank" rel="noreferrer">agent/docs/MCP-UPGRADE-ANALYSIS.md#L148-L189</a></li></ul><h2 id="故障排查与调试指南" tabindex="-1">故障排查与调试指南 <a class="header-anchor" href="#故障排查与调试指南" aria-label="Permalink to &quot;故障排查与调试指南&quot;">​</a></h2><h3 id="常见错误与定位" tabindex="-1">常见错误与定位 <a class="header-anchor" href="#常见错误与定位" aria-label="Permalink to &quot;常见错误与定位&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>排查步骤</th></tr></thead><tbody><tr><td>连接失败</td><td>缺少 url/command、URL 无效、命令被拦截</td><td>检查 transport 对应必填字段；查看 stdio 命令安全检查日志</td></tr><tr><td>工具列表为空</td><td>服务器未返回 tools、连接未成功</td><td>检查 <code>connect()</code> 返回值；确认服务器支持 <code>tools/list</code></td></tr><tr><td>工具调用失败</td><td>参数不合法、服务器返回 error、网络异常</td><td>查看 <code>callTool()</code> 返回的 error 字段；检查输入 schema</td></tr><tr><td>服务未连接</td><td>未调用 connect、服务被禁用、连接断开</td><td>检查 <code>registry.js</code> 中 client 状态；确认 enabled 字段</td></tr></tbody></table><h3 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to &quot;调试技巧&quot;">​</a></h3><ol><li><strong>使用测试服务器</strong>：<code>agent/test/mcp-test-server.cjs</code> 提供本地 stdio MCP 服务器，可用于验证客户端行为。</li><li><strong>运行单元测试</strong>：<code>agent/test/mcp-client-test.js</code> 演示连接、状态查询、工具调用和断开的完整流程。</li><li><strong>查看日志</strong>：Agent 端会输出 <code>[MCP]</code> 前缀的连接和调用日志。</li><li><strong>检查配置</strong>：确认 <code>~/.ai-helper-agent/mcp_servers.json</code> 中配置正确。</li><li><strong>浏览器控制台</strong>：扩展端 Background 会缓存 MCP 工具列表，可通过存储键 <code>mcpTools</code> 查看。</li></ol><h3 id="实际连接示例" tabindex="-1">实际连接示例 <a class="header-anchor" href="#实际连接示例" aria-label="Permalink to &quot;实际连接示例&quot;">​</a></h3><p>以下示例描述如何通过 Agent API 连接一个 stdio MCP Server：</p><ol><li>添加 MCP Server： <ul><li>调用 <code>POST /api/mcp/servers</code>。</li><li>body 包含 <code>id</code>、<code>name</code>、<code>transport=stdio</code>、<code>command</code>、<code>args</code>、<code>enabled=true</code>。</li></ul></li><li>连接 MCP Server： <ul><li>调用 <code>POST /api/mcp/servers/connect</code>。</li><li>body 包含 <code>id</code>。</li></ul></li><li>获取工具列表： <ul><li>调用 <code>GET /api/mcp/tools</code>。</li></ul></li><li>调用工具： <ul><li>调用 <code>POST /api/mcp/call</code>。</li><li>body 包含 <code>serverId</code>、<code>toolName</code>、<code>args</code>。</li></ul></li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-client-test.js#L1-L52" target="_blank" rel="noreferrer">agent/test/mcp-client-test.js#L1-L52</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-test-server.cjs#L1-L234" target="_blank" rel="noreferrer">agent/test/mcp-test-server.cjs#L1-L234</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本实现以 <code>McpClient</code> 为核心，结合 <code>registry.js</code> 的多服务管理和 <code>mcp-config.js</code> 的配置持久化，提供了完整的 MCP 客户端能力。其特点包括：</p><ul><li>支持四种传输协议，适配不同 MCP Server 部署形态。</li><li>工具自动发现流程清晰，连接成功后立即拉取工具列表。</li><li>工具调用链路简洁，错误信息经过国际化处理。</li><li>配置管理具备内存缓存和写入锁，提升安全性和性能。</li><li>当前实现未内置连接池和重试机制，但可通过上层扩展实现。</li></ul><p>未来可考虑的方向包括：</p><ul><li>增加连接超时和重试策略。</li><li>支持 MCP SDK v2.x 的新特性，如 <code>server/discover</code>、<code>Mcp-Method</code> header 等。</li><li>对 SSE 和 WebSocket 传输进行兼容性评估和迁移规划。</li><li>增强工具参数校验和 schema 验证能力。</li></ul>`,139)])])}const u=t(i,[["render",c]]);export{p as __pageData,u as default};
